def explain_combo(combo,passed,failed,values,*,symbol=None,signal_time=None,data_freshness_warning=None):
    return {"combo":combo.get("name"),"category":combo.get("category"),"symbol":symbol,"signal_time":signal_time,"direction":combo.get("entry",{}).get("direction","long"),"confirmations_passed":passed,"confirmations_failed":failed,"indicator_values":values,"exit_plan":combo.get("exit",{}),"risk_notes":combo.get("risk",{}),"data_freshness_warning":data_freshness_warning,"explanation":f"{combo.get('name')} accepted {len(passed)} component confirmations under {combo.get('logic',{}).get('mode','all')} logic. Failed components: {', '.join(failed) or 'none'}."}
